  values ('gm_wnba_2024_20240915_phx_at_chi', 'gp_KJNJ39KCDGRS', 'te_chicago_sky_2024', true, false, null, 2400, 18, 7, 13, 4, 6, 0, 2, 3, 6, 9, 1, 1, 1, 2, 3, null, v_doc_1, v_run, 'wbh_notes_boxscore_v1', 'official_team_game_notes:roster_exact', 0.95);
  insert into public.wbh_player_game_stats (game_id, person_id, team_edition_id, started, did_not_play, dnp_reason, seconds_played, points, field_goals_made, field_goals_attempted, three_pointers_made, three_pointers_attempted, free_throws_made, free_throws_attempted, offensive_rebounds, defensive_rebounds, rebounds, assists, steals, blocks, turnovers, personal_fouls, plus_minus, source_document_id, ingestion_run_id, transformation_version, derivation, confidence)
  values ('gm_wnba_2024_20240915_phx_at_chi', 'gp_GT3A7XEGE909', 'te_chicago_sky_2024', true, false, null, 1560, 6, 3, 5, 0, 1, 0, 0, 0, 6, 6, 7, 0, 0, 0, 2, null, v_doc_1, v_run, 'wbh_notes_boxscore_v1', 'official_team_game_notes:roster_exact', 0.95);
  insert into public.wbh_player_game_stats (game_id, person_id, team_edition_id, started, did_not_play, dnp_reason, seconds_played, points, field_goals_made, field_goals_attempted, three_pointers_made, three_pointers_attempted, free_throws_made, free_throws_attempted, offensive_rebounds, defensive_rebounds, rebounds, assists, steals, blocks, turnovers, personal_fouls, plus_minus, source_document_id, ingestion_run_id, transformation_version, derivation, confidence)
  values ('gm_wnba_2024_20240915_phx_at_chi', 'gp_97VGE49KWW11', 'te_chicago_sky_2024', true, false, null, 1860, 10, 5, 13, 0, 1, 0, 0, 4, 4, 8, 1, 0, 0, 0, 1, null, v_doc_1, v_run, 'wbh_notes_boxscore_v1', 'official_team_game_notes:roster_exact', 0.95);
  insert into public.wbh_player_game_stats (game_id, person_id, team_edition_id, started, did_not_play, dnp_reason, seconds_played, points, field_goals_made, field_goals_attempted, three_pointers_made, three_pointers_attempted, free_throws_made, free_throws_attempted, offensive_rebounds, defensive_rebounds, rebounds, assists, steals, blocks, turnovers, personal_fouls, plus_minus, source_document_id, ingestion_run_id, transformation_version, derivation, confidence)
  values ('gm_wnba_2024_20240915_phx_at_chi', 'gp_5A62X62V0ZT7', 'te_chicago_sky_2024', true, false, null, 2160, 17, 5, 13, 5, 11, 2, 3, 1, 4, 5, 7, 1, 0, 2, 2, null, v_doc_1, v_run, 'wbh_notes_boxscore_v1', 'official_team_game_notes:league_unique_in_club_document', 0.95);

  select count(*) into v_rows
    from public.wbh_player_game_stats s
    join public.wbh_ingestion_runs r on r.run_id = s.ingestion_run_id
   where r.scope->>'dataset' = v_dataset;
  if v_rows <> 139 then
    raise exception 'wbh: expected 139 player rows, wrote %', v_rows using errcode = 'P0001';
  end if;

  -- the load re-proves its own arithmetic: every team-game must equal the canonical team score
  select count(*) into v_bad from (
    select s.game_id, s.team_edition_id, sum(s.points) as pts,
           (select gt.points from public.wbh_game_teams gt
             where gt.game_id = s.game_id and gt.team_edition_id = s.team_edition_id) as canon
      from public.wbh_player_game_stats s
      join public.wbh_ingestion_runs r on r.run_id = s.ingestion_run_id
     where r.scope->>'dataset' = v_dataset and not s.did_not_play
     group by 1, 2
  ) t where t.pts is distinct from t.canon;
  if v_bad <> 0 then
    raise exception 'wbh: % team-games do not reconcile to the canonical score', v_bad using errcode = 'P0001';
  end if;

  if exists (select 1 from public.wbh_player_game_stats s
               join public.wbh_ingestion_runs r on r.run_id = s.ingestion_run_id
              where r.scope->>'dataset' = v_dataset
                and (s.field_goals_made > s.field_goals_attempted
                  or s.three_pointers_made > s.three_pointers_attempted
                  or s.free_throws_made > s.free_throws_attempted)) then
    raise exception 'wbh: a row has made greater than attempted' using errcode = 'P0001';
  end if;

  -- a game becomes box_score complete only when both clubs are present and reconciled; nothing here
  -- claims 'full', which would require play-by-play
  update public.wbh_games g
     set completeness = 'box_score', ingestion_run_id = v_run
   where g.edition_id = 'wnba_2024'
     and g.completeness = 'score_only'
     and (select count(distinct s.team_edition_id) from public.wbh_player_game_stats s
           join public.wbh_ingestion_runs r on r.run_id = s.ingestion_run_id
          where s.game_id = g.game_id and r.scope->>'dataset' = v_dataset) = 2;
  get diagnostics v_games = row_count;

  update public.wbh_ingestion_runs
     set status = 'ok',
         counts = jsonb_build_object('player_rows', v_rows, 'games_upgraded_to_box_score', v_games),
         finished_at = clock_timestamp()
   where run_id = v_run;
end $seed$;

